<?php $title='Analytics';require __DIR__.'/_layout.php';if(!can_manage('analytics'))exit('Forbidden');$daily=db()->query("SELECT DATE(viewed_at) day,COUNT(*) views FROM post_views GROUP BY DATE(viewed_at) ORDER BY day DESC LIMIT 30")->fetchAll();$popular=db()->query("SELECT title,view_count FROM posts ORDER BY view_count DESC LIMIT 10")->fetchAll();?><h1>Analytics</h1><div class="stats"><div class="stat"><b>Total views</b><h2><?=number_format((int)db()->query("SELECT COUNT(*) FROM post_views")->fetchColumn())?></h2></div></div><h2>Daily views</h2><table class="table"><tr><th>Date</th><th>Views</th></tr><?php foreach($daily as $d):?><tr><td><?=e($d['day'])?></td><td><?=e($d['views'])?></td></tr><?php endforeach;?></table><h2>Popular posts</h2><table class="table"><tr><th>Post</th><th>Views</th></tr><?php foreach($popular as $p):?><tr><td><?=e($p['title'])?></td><td><?=e($p['view_count'])?></td></tr><?php endforeach;?></table><?php require __DIR__.'/_footer.php';?>